<?php
/** Slice 7 proof 3 — the routes of design §8 as a key's person: folders, libraries, documents (read, download, text, rename, describe, move, tags, trash), search, the graph (503 without the engine), links; the codes; every call logged `api` under the key. */
require __DIR__ . '/lib.php';
$s = seed_texts();
$board = $s['board_root']; $contracts = $s['contracts']; $acme = $s['board_doc'];
$km = mint_key(27, 'Marco API')['token']; $kp = mint_key(26, 'Priya API')['token']; $kb = mint_key(28, 'Bea API')['token']; $kd = mint_key(30, 'Dana API')['token'];
$mkid = (int) one("SELECT id FROM mcp_access_tokens WHERE member_id = 27 AND label = 'Marco API'");
$since = last_activity_id();

echo "1. Health, me, libraries\n";
$r = req('GET', '/api/v1/health');
ok($r['code'] === 200 && json_decode($r['body'], true)['application'] === 'doccloud', 'GET /health needs no key');
$r = api('GET', '/api/v1/libraries', $km);
$libs = $r['json']['libraries'] ?? [];
ok($r['code'] === 200 && in_array('personal', array_column($libs, 'kind'), true) && in_array('SMOKE Board', array_column($libs, 'name'), true), 'GET /libraries: Marco\'s personal library and the Board');
ok(!isset($libs[0]['storage_path']) && isset($libs[0]['my_level'], $libs[0]['root_folder_id']), 'a library carries its level and root folder, nothing internal');
ok(!in_array('SMOKE Priya', array_column(api('GET', '/api/v1/libraries', $kb)['json']['libraries'] ?? [], 'name'), true), 'Bea\'s libraries do not include the Board');

echo "2. A folder\n";
$real = real_doc(27, $contracts, 'api-real.txt', 'api1', 3000);
$r = api('GET', '/api/v1/folders/' . $contracts, $km);
$j = $r['json'];
ok($r['code'] === 200 && $j['folder']['folder_id'] === $contracts && $j['folder']['name'] === 'Contracts' && $j['folder']['my_level'] === 'manage', 'GET /folders/{id}: the folder with Marco\'s level');
ok(array_column($j['crumbs'], 'name') === ['SMOKE Board', 'Contracts'], 'the crumbs run from the library root');
ok($j['total'] >= 2 && in_array('acme-msa.pdf', array_column($j['rows'], 'name'), true) && $j['rows'][0]['kind'] === 'document', 'the rows: documents with kind, name, size, tags');
ok(!isset($j['rows'][0]['storage_path']) && !str_contains($r['body'], 'storage_path'), 'no storage path anywhere in the answer');
$sub = folder_in($contracts, 'Q1');
$r = api('GET', '/api/v1/folders/' . $contracts . '?sort=updated&dir=desc&kind=folder', $km);
ok($r['json']['rows'][0]['name'] === 'Q1' && count($r['json']['rows']) === 1, 'sort, dir and kind filters work (kind=folder lists only Q1)');
ok(api('GET', '/api/v1/folders/' . $contracts . '?per=1&page=2', $km)['json']['page'] === 2, 'paging');
ok(api('GET', '/api/v1/folders/' . root_of(26), $km)['code'] === 404, 'another person\'s personal library: 404');
ok(api('GET', '/api/v1/folders/' . $contracts, $kb)['code'] === 404, 'a folder Bea may not see: 404 (the same as a missing one)');
ok(api('GET', '/api/v1/folders/999999', $km)['code'] === 404 && api('GET', '/api/v1/folders/abc', $km)['code'] === 404, 'a missing folder / a bad id: 404');
pdo()->exec("SELECT set_config('app.member_id', '27', false)"); pdo()->exec("SELECT dc_folder_trash($sub, 27)");
ok(api('GET', '/api/v1/folders/' . $sub, $km)['code'] === 404, 'a trashed folder is not served: 404');

echo "3. Folders made\n";
$name = 'Via API ' . bin2hex(random_bytes(3));
$r = api('POST', '/api/v1/folders', $km, ['json' => ['parent' => $contracts, 'name' => $name]]);
ok($r['code'] === 201 && $r['json']['folder_id'] > 0 && one('SELECT name FROM folders WHERE id = :f', ['f' => $r['json']['folder_id']]) === $name, 'POST /folders: 201 {folder_id}');
$newF = $r['json']['folder_id'];
$ev = last_event('folder.create');
ok($ev['source'] === 'api' && (int) $ev['token_id'] === $mkid && (int) $ev['actor_member_id'] === 27, 'folder.create is logged with source api, the key\'s token_id and the person');
$r = api('POST', '/api/v1/folders', $km, ['json' => ['parent' => $contracts, 'name' => $name]]);
ok($r['code'] === 422 && isset($r['json']['error']['fields']['name']), 'a taken name: 422 on the field');
ok(api('POST', '/api/v1/folders', $km, ['json' => ['parent' => $contracts]])['code'] === 422, 'no name: 422');
ok(api('POST', '/api/v1/folders', $kp, ['json' => ['parent' => root_of(27), 'name' => 'nope']])['code'] === 404, 'a parent the key\'s person cannot see: 404');
ok(api('POST', '/api/v1/folders', $km, ['raw' => '{not json', 'headers' => ['Content-Type: application/json']])['code'] === 400, 'a body that is not JSON: 400');
$pol = $s['pol_root'];
$r = api('POST', '/api/v1/folders', $kb, ['json' => ['parent' => $pol, 'name' => 'Bea may not']]);
ok($r['code'] === 403 && str_contains($r['json']['error']['message'], 'You may not'), 'a parent seen at view only (the shared handbook library): 403 in words');

echo "4. A document\n";
$r = api('GET', '/api/v1/documents/' . $acme, $km);
$j = $r['json'];
ok($r['code'] === 200 && $j['document']['document_id'] === $acme && $j['document']['name'] === 'acme-msa.pdf' && $j['document']['my_level'] === 'manage' && is_array($j['versions']) && $j['versions'][0]['version_no'] === 1 && $j['versions'][0]['is_current'] === true, 'GET /documents/{id}: the document, its versions, level');
ok(array_key_exists('tags', $j) && $j['document']['owner_name'] === 'SMOKE Marco' && !str_contains($r['body'], 'storage_path'), 'tags, owner name, no storage path');
ok(api('GET', '/api/v1/documents/' . $s['priya_doc'], $km)['code'] === 404 && api('GET', '/api/v1/documents/' . $acme, $kb)['code'] === 404, 'a document the person may not see: 404');
ok(api('GET', '/api/v1/documents/' . $s['guest_doc'], $km)['code'] === 200, 'Marco\'s own document shared with a guest: his, 200');
$ev = last_event('document.read');
ok($ev !== null && $ev['source'] === 'api' && (int) $ev['token_id'] === $mkid && json_decode($ev['after'], true)['key_label'] === 'Marco API', 'document.read is logged api, with the key\'s label');

echo "5. The bytes and the text\n";
$r = api('GET', '/api/v1/documents/' . $real . '/download', $km);
$blob = file_get_contents(blob_of($real)[0]);
ok($r['code'] === 200 && $r['body'] === $blob && strlen($r['body']) === 3000, 'GET /download: the bytes, whole');
ok(header_of($r, 'X-Content-Type-Options') === 'nosniff' && str_starts_with((string) header_of($r, 'Content-Disposition'), 'attachment;') && header_of($r, 'Content-Type') === 'application/octet-stream', 'attachment, nosniff, never an inline type');
$r2 = api('GET', '/api/v1/documents/' . $real . '/download', $km, ['headers' => ['Range: bytes=0-99']]);
ok($r2['code'] === 206 && strlen($r2['body']) === 100 && str_contains((string) header_of($r2, 'Content-Range'), '0-99/3000'), 'a Range request: 206, 100 bytes');
ok(api('GET', '/api/v1/documents/' . $real . '/download', $km, ['headers' => ['If-None-Match: "' . hash('sha256', $blob) . '"']])['code'] === 304, 'If-None-Match with the sha256: 304');
ok(api('GET', '/api/v1/documents/' . $real . '/download?version=1', $km)['code'] === 200 && api('GET', '/api/v1/documents/' . $real . '/download?version=9', $km)['code'] === 404, '?version=1 serves it; an unknown version is 404');
ok(api('GET', '/api/v1/documents/' . $real . '/download', $kb)['code'] === 404, 'the bytes of a document Bea may not see: 404');
$ev = last_event('document.download');
ok($ev !== null && $ev['source'] === 'api' && (int) $ev['token_id'] === $mkid && json_decode($ev['after'], true)['door'] === 'api' && (int) $ev['document_id'] === $real, 'document.download is logged with the door api and the token');
$p = pdo(); $pv = (int) one('SELECT current_version_id FROM documents WHERE id = :d', ['d' => $acme]);
$p->prepare("UPDATE document_text SET text = :t, char_count = :c, pages = CAST(:p AS jsonb) WHERE version_id = :v")->execute(['t' => 'Page one text. Page two text here.', 'c' => 34, 'p' => json_encode([['page_no' => 1, 'char_from' => 0, 'char_to' => 14], ['page_no' => 2, 'char_from' => 15, 'char_to' => 34]]), 'v' => $pv]);
$r = api('GET', '/api/v1/documents/' . $acme . '/text', $km);
ok($r['code'] === 200 && $r['json']['text'] === 'Page one text. Page two text here.' && count($r['json']['pages']) === 2 && $r['json']['char_count'] === 34 && $r['json']['truncated'] === false && $r['json']['document_id'] === $acme, 'GET /text: the text, its two pages, the count');
ok(api('GET', '/api/v1/documents/' . $acme . '/text', $kb)['code'] === 404, 'the text of a document Bea may not see: 404');
$r = api('GET', '/api/v1/documents/' . $real . '/text', $km);
ok($r['code'] === 200 && $r['json']['text'] === '' && $r['json']['pages'] === [], 'a document with no extracted text yet: an empty text, no pages');
$ev = last_event('document.text');
ok(!str_contains(json_encode($ev), 'Page one'), 'document.text is logged without the words');

echo "6. Rename, describe, move\n";
$d1 = seed_doc($contracts, 'api-patch.pdf', 27, 'patch me');
$r = api('PATCH', '/api/v1/documents/' . $d1, $km, ['json' => ['name' => 'api-renamed.pdf', 'description' => 'Via the API']]);
ok($r['code'] === 200 && $r['json']['document']['name'] === 'api-renamed.pdf' && $r['json']['document']['description'] === 'Via the API', 'PATCH name and description: 200 {document}');
$ev = q("SELECT action FROM activity_log WHERE document_id = :d AND source = 'api' ORDER BY id", ['d' => $d1]);
ok(array_column($ev, 'action') === ['document.rename', 'document.describe'], 'the handlers logged document.rename and document.describe with source api');
$d2 = seed_doc($contracts, 'api-taken.pdf', 27, 'taken'); 
ok(api('PATCH', '/api/v1/documents/' . $d1, $km, ['json' => ['name' => 'api-taken.pdf']])['code'] === 422, 'renaming onto a taken name: 422');
ok(api('PATCH', '/api/v1/documents/' . $d1, $km, ['json' => (object) []])['code'] === 422, 'PATCH with nothing to change: 422');
$r = api('PATCH', '/api/v1/documents/' . $d1, $km, ['json' => ['folder' => $board]]);
ok($r['code'] === 200 && (int) one('SELECT folder_id FROM documents WHERE id = :d', ['d' => $d1]) === $board && $r['json']['document']['folder_id'] === $board, 'PATCH folder moves it');
$r = api('PATCH', '/api/v1/documents/' . $d1, $kb, ['json' => ['name' => 'x.pdf']]);
ok($r['code'] === 404, 'a document Bea may not see: 404');
$hb = seed_doc($pol, 'api-handbook-note.pdf', 27, 'hb');
$ev0 = (int) one('SELECT folder_id FROM documents WHERE id = :d', ['d' => $s['priya_doc']]);
$r = api('PATCH', '/api/v1/documents/' . $s['priya_doc'], $kp, ['json' => ['folder' => $pol]]);
ok($r['code'] === 403 && (int) one('SELECT folder_id FROM documents WHERE id = :d', ['d' => $s['priya_doc']]) === $ev0, 'a move into a folder Priya sees at view only: 403, nothing moved');
$r = api('PATCH', '/api/v1/documents/' . $hb, $kp, ['json' => ['name' => 'nope.pdf']]);
ok($r['code'] === 403, 'renaming a document at view only: 403');
pdo()->exec("SELECT set_config('app.member_id', '26', false)"); one('SELECT dc_document_lock(:d, 26)', ['d' => $d2]);
$r = api('PATCH', '/api/v1/documents/' . $d2, $km, ['json' => ['name' => 'api-locked.pdf']]);
ok($r['code'] === 423 && str_contains($r['json']['error']['message'], 'Locked by'), 'a document locked by someone else: 423 with the holder named');
pdo()->exec("UPDATE documents SET locked_by = NULL, locked_at = NULL, lock_expires_at = NULL WHERE id = $d2");

echo "7. Tags\n";
$r = api('PUT', '/api/v1/documents/' . $d2 . '/tags', $km, ['json' => ['tags' => ['scan', 'Mail Room']]]);
ok($r['code'] === 200 && $r['json']['tags'] === ['mail-room', 'scan'] || ($r['code'] === 200 && array_diff($r['json']['tags'], ['mail-room', 'scan']) === []), 'PUT /tags sets them: a label becomes its slug (' . implode(',', $r['json']['tags'] ?? []) . ')');
$r = api('PUT', '/api/v1/documents/' . $d2 . '/tags', $km, ['json' => ['tags' => ['scan', 'invoice']]]);
ok($r['code'] === 200 && array_diff($r['json']['tags'], ['scan', 'invoice']) === [] && array_diff(['scan', 'invoice'], $r['json']['tags']) === [] && $r['json']['removed'] === ['mail-room'], 'a second PUT applies the new and removes the rest');
ok(api('GET', '/api/v1/documents/' . $d2, $km)['json']['tags'] === $r['json']['tags'] || array_diff(api('GET', '/api/v1/documents/' . $d2, $km)['json']['tags'], $r['json']['tags']) === [], 'the document shows them');
$acts = array_column(q("SELECT action FROM activity_log WHERE document_id = :d AND source = 'api' AND action LIKE 'tag.%' ORDER BY id", ['d' => $d2]), 'action');
ok($acts === ['tag.apply', 'tag.apply', 'tag.apply', 'tag.remove'], 'tag.apply and tag.remove were logged by the slice\'s handlers (source api)');
$r = api('PUT', '/api/v1/documents/' . $d2 . '/tags', $km, ['json' => ['tags' => []]]);
ok($r['code'] === 200 && $r['json']['tags'] === [], 'an empty list removes every tag');
ok(api('PUT', '/api/v1/documents/' . $d2 . '/tags', $km, ['json' => ['tags' => 'scan']])['code'] === 422, 'tags that is not a list: 422');
ok(api('PUT', '/api/v1/documents/' . $hb . '/tags', $kp, ['json' => ['tags' => ['x']]])['code'] === 403, 'tags on a document at view only: 403');
ok(api('PUT', '/api/v1/documents/' . $acme . '/tags', $kb, ['json' => ['tags' => ['x']]])['code'] === 404, 'tags on a document Bea cannot see: 404');
ok(api('PUT', '/api/v1/documents/' . $d2, $km, ['json' => ['tags' => []]])['code'] === 405, 'PUT on the document itself: 405 method_not_allowed');

echo "8. The trash\n";
$d3 = seed_doc($contracts, 'api-trash.pdf', 27, 'bin');
ok(api('DELETE', '/api/v1/documents/' . $d3, $kp)['code'] === 403 || api('DELETE', '/api/v1/documents/' . $d3, $kp)['code'] === 404, 'Priya (edit on the Board) may not trash Marco\'s document: refused');
$r = api('DELETE', '/api/v1/documents/' . $d3, $km);
ok($r['code'] === 204 && $r['body'] === '' && one('SELECT trashed_at IS NOT NULL FROM documents WHERE id = :d', ['d' => $d3]), 'DELETE: 204 with no body, the document in the trash');
ok(api('DELETE', '/api/v1/documents/' . $d3, $km)['code'] === 422, 'again: 422 (already in the trash)');
ok(api('GET', '/api/v1/documents/' . $d3 . '/download', $km)['code'] === 404, 'a trashed document is not served');
ok(api('DELETE', '/api/v1/documents/' . $acme, $kb)['code'] === 404, 'a document Bea cannot see: 404');

echo "9. Search\n";
$r = api('POST', '/api/v1/search', $km, ['json' => ['q' => 'termination']]);
$names = array_column($r['json']['rows'] ?? [], 'name');
ok($r['code'] === 200 && $r['json']['total'] >= 2 && in_array('minutes-jan.docx', $names, true) && isset($r['json']['took_ms']) && str_contains($r['body'], '<mark>'), 'POST /search: rows with marked excerpts, a total, took_ms');
ok(!in_array('my-notes.md', $names, true) && !in_array('design.pdf', $names, true), 'nothing Marco may not see: Priya\'s notes and the Engineering design are absent');
$r = api('POST', '/api/v1/search', $kp, ['json' => ['q' => 'termination']]);
ok(in_array('my-notes.md', array_column($r['json']['rows'], 'name'), true), 'Priya\'s key does find her notes');
$r = api('POST', '/api/v1/search', $km, ['json' => ['q' => 'termination', 'filters' => ['kind' => 'pdf']]]);
ok($r['code'] === 200 && array_diff(array_column($r['json']['rows'], 'mime_kind'), ['pdf']) === [], 'filters: kind pdf');
ok(api('POST', '/api/v1/search', $km, ['json' => (object) []])['code'] === 422 && api('POST', '/api/v1/search', $km, ['json' => ['q' => str_repeat('a', 201)]])['code'] === 422, 'no query: 422; over 200 characters: 422');
ok(api('GET', '/api/v1/search', $km)['code'] === 405, 'GET /search: 405');
$long = str_repeat('word ', 40);
api('POST', '/api/v1/search', $km, ['json' => ['q' => substr($long, 0, 199)]]);
$ev = last_event('search.keyword');
ok($ev['source'] === 'api' && (int) $ev['token_id'] === $mkid && mb_strlen(json_decode($ev['after'], true)['query']) <= 120, 'search.keyword is logged api with the key, the query cut at 120');

echo "10. The graph\n";
$r = api('POST', '/api/v1/graph/find', $km, ['json' => ['q' => 'termination risk']]);
ok($r['code'] === 503 && $r['json']['error']['code'] === 'graph_unavailable' && str_contains($r['json']['error']['message'], 'keyword search still works'), 'POST /graph/find without the engine: 503 graph_unavailable, and the keyword search is named');
ok(api('POST', '/api/v1/graph/find', $km, ['json' => (object) []])['code'] === 422, 'no query: 422');
ok($r['code'] === 503 && api('POST', '/api/v1/search', $km, ['json' => ['q' => 'termination']])['code'] === 200, 'the keyword search is unaffected by the engine');
$ev = last_event('search.graph');
ok($ev !== null && $ev['source'] === 'api' && !str_contains(json_encode($ev), 'termination risk'), 'search.graph is logged api, without the words');

echo "11. Links\n";
$r = api('POST', '/api/v1/links', $km, ['json' => ['document' => $acme, 'label' => 'For the auditor', 'days' => 7, 'allow_download' => true]]);
ok($r['code'] === 201 && preg_match('#/s/[a-f0-9]{48}$#', (string) $r['json']['url']) && $r['json']['link_id'] > 0 && $r['json']['expires_at'] !== null, 'POST /links: 201 {link_id, url, expires_at} — the URL once');
$lurl = $r['json']['url'];
ok(req('GET', parse_url($lurl, PHP_URL_PATH))['code'] === 200, 'the link opens for anyone holding it');
ok((int) one("SELECT count(*) FROM activity_log WHERE route ~ '/[sr]/[a-f0-9]{48}'") === 0 && (int) one("SELECT count(*) FROM activity_log WHERE action = 'link.open' AND route LIKE 'GET /s/%'") >= 1, 'opening it is logged link.open with the token cut from the route (GET /s/…)');
$ev = last_event('link.make');
ok($ev['source'] === 'api' && (int) $ev['token_id'] === $mkid && !str_contains(json_encode($ev), substr(parse_url($lurl, PHP_URL_PATH), 3)), 'link.make is logged api and never carries the token');
$r = api('POST', '/api/v1/links', $km, ['json' => ['folder' => $contracts, 'kind' => 'request', 'label' => 'Send us scans', 'days' => 3]]);
ok($r['code'] === 201 && str_contains($r['json']['url'], '/r/') && $r['json']['kind'] === 'request', 'kind request on a folder: a file request, /r/…');
ok(api('POST', '/api/v1/links', $km, ['json' => ['document' => $acme]])['code'] === 422, 'no label: 422');
ok(api('POST', '/api/v1/links', $kp, ['json' => ['document' => $acme, 'label' => 'x']])['code'] === 403, 'a member at edit (not manage) may not link it: 403');
ok(api('POST', '/api/v1/links', $kb, ['json' => ['document' => $acme, 'label' => 'x']])['code'] === 404, 'a document Bea cannot see: 404');
ok(api('POST', '/api/v1/links', $km, ['json' => ['label' => 'x']])['code'] === 422 && api('POST', '/api/v1/links', $km, ['json' => ['document' => $acme, 'label' => 'x', 'kind' => 'odd']])['code'] === 422, 'no target / an odd kind: 422');
ok(api('POST', '/api/v1/links', $km, ['json' => ['document' => $acme, 'label' => 'pw', 'password' => 'abc']])['code'] === 422, 'a password under 4 characters: 422');

echo "12. Methods, unknown routes, headers, the log\n";
ok(api('DELETE', '/api/v1/me', $km)['code'] === 405 && api('POST', '/api/v1/libraries', $km)['code'] === 405 && api('POST', '/api/v1/documents/' . $acme, $km, ['json' => (object) []])['code'] === 405, 'the wrong method: 405');
ok(req('GET', '/api/v1/nothing')['code'] === 404 && req('GET', '/api/v1/')['code'] === 404, 'an unknown route under /api/v1: 404');
$r = api('GET', '/api/v1/me', $km, ['headers' => ['Origin: https://evil.example']]);
ok(header_of($r, 'Access-Control-Allow-Origin') === null && header_of($r, 'Set-Cookie') === null, 'no CORS header (no origin is configured) and no session cookie on an API answer');
ok(strtolower((string) header_of($r, 'Content-Type')) === 'application/json; charset=utf-8' && header_of($r, 'Cache-Control') === 'no-store', 'JSON, never cached');
$n = (int) one("SELECT count(*) FROM activity_log WHERE id > :s AND source = 'api' AND token_id = :t", ['s' => $since, 't' => $mkid]);
ok($n >= 20, 'every call of the key left a row with source api and its token_id (' . $n . ')');
ok((int) one("SELECT count(*) FROM activity_log WHERE id > :s AND (after::text ~ 'dck_[0-9a-f]{48}' OR route ~ 'dck_[0-9a-f]{48}')", ['s' => $since]) === 0, 'no key is in any log row');
ok((int) one("SELECT count(*) FROM activity_log WHERE id > :s AND token_id IS NOT NULL AND source <> 'api' AND action NOT LIKE 'key.%'", ['s' => $since]) === 0, 'rows with a token_id are source api (the key events aside)');
finish();
